CREATE OR REPLACE FUNCTION public.btcsp_delete_project_v1(p_id uuid, p_expected_meta_updated_at timestamp with time zone, p_expected_version integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
 v_uid uuid;
 v_existing record;
 v_snapshot record;
 v_current_version integer;
BEGIN
 v_uid:=auth.uid();
 IF v_uid IS NULL THEN
   RAISE EXCEPTION 'BTCSP_NOT_AUTHENTICATED' USING ERRCODE='28000';
 END IF;
 IF p_id IS NULL OR p_expected_meta_updated_at IS NULL THEN
   RAISE EXCEPTION 'BTCSP_INVALID_DATA' USING ERRCODE='22023';
 END IF;
 SELECT * INTO v_existing FROM public.projects
   WHERE id=p_id AND owner_id=v_uid FOR UPDATE;
 IF NOT FOUND OR v_existing.updated_at IS DISTINCT FROM p_expected_meta_updated_at THEN
   RAISE EXCEPTION 'BTCSP_VERSION_CONFLICT' USING ERRCODE='P0001';
 END IF;
 SELECT * INTO v_snapshot FROM public.project_snapshots
   WHERE project_id=p_id AND owner_id=v_uid FOR UPDATE;
 IF FOUND THEN v_current_version:=v_snapshot.version;
 ELSE v_current_version:=NULL; END IF;
 IF v_current_version IS DISTINCT FROM p_expected_version THEN
   RAISE EXCEPTION 'BTCSP_VERSION_CONFLICT' USING ERRCODE='P0001';
 END IF;
 DELETE FROM public.projects WHERE id=p_id AND owner_id=v_uid;
 RETURN true;
END
$function$

CREATE OR REPLACE FUNCTION public.btcsp_save_project_v1(p_id uuid, p_name text, p_mode text, p_capital numeric, p_archived boolean, p_payload jsonb, p_expected_meta_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_expected_version integer DEFAULT NULL::integer)
 RETURNS TABLE(meta_updated_at timestamp with time zone, snapshot_version integer)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid;
  v_existing record;
  v_snapshot record;
  v_meta timestamptz;
  v_version integer;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'BTCSP_NOT_AUTHENTICATED' USING ERRCODE='28000';
  END IF;
  IF p_id IS NULL OR p_name IS NULL OR char_length(btrim(p_name)) NOT BETWEEN 2 AND 65
     OR p_mode NOT IN ('demo','real') OR p_mode IS NULL
     OR p_capital IS NULL OR p_capital NOT BETWEEN 100 AND 1000000000
     OR p_archived IS NULL OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object'
     OR octet_length(p_payload::text)>1500000 THEN
     RAISE EXCEPTION 'BTCSP_INVALID_DATA' USING ERRCODE='22023';
  END IF;

  -- Lock project row: serialize same-project writes across clients, then check
  -- both expected metadata timestamp and expected snapshot revision.
  SELECT * INTO v_existing FROM public.projects
    WHERE id=p_id AND owner_id=v_uid FOR UPDATE;
  IF FOUND THEN
    IF v_existing.updated_at IS DISTINCT FROM p_expected_meta_updated_at THEN
      RAISE EXCEPTION 'BTCSP_VERSION_CONFLICT' USING ERRCODE='P0001';
    END IF;
    SELECT * INTO v_snapshot FROM public.project_snapshots
      WHERE project_id=p_id AND owner_id=v_uid FOR UPDATE;
    IF FOUND THEN
      IF v_snapshot.version IS DISTINCT FROM p_expected_version THEN
        RAISE EXCEPTION 'BTCSP_VERSION_CONFLICT' USING ERRCODE='P0001';
      END IF;
      IF v_snapshot.payload IS DISTINCT FROM p_payload THEN
        UPDATE public.project_snapshots
          SET payload=p_payload, version=v_snapshot.version+1
          WHERE project_id=p_id AND owner_id=v_uid RETURNING version INTO v_version;
      ELSE
        v_version := v_snapshot.version;
      END IF;
    ELSE
      IF p_expected_version IS NOT NULL THEN
        RAISE EXCEPTION 'BTCSP_VERSION_CONFLICT' USING ERRCODE='P0001';
      END IF;
      INSERT INTO public.project_snapshots(project_id,owner_id,payload,version)
        VALUES(p_id,v_uid,p_payload,1) RETURNING version INTO v_version;
    END IF;
    IF v_existing.name IS DISTINCT FROM p_name
      OR v_existing.mode IS DISTINCT FROM p_mode
      OR v_existing.capital IS DISTINCT FROM p_capital
      OR v_existing.archived IS DISTINCT FROM p_archived THEN
      UPDATE public.projects
        SET name=btrim(p_name),mode=p_mode,capital=p_capital,archived=p_archived
        WHERE id=p_id AND owner_id=v_uid
        RETURNING updated_at INTO v_meta;
    ELSE
      v_meta := v_existing.updated_at;
    END IF;
  ELSE
    -- A new project must not overwrite an existing or deleted one.
    IF p_expected_meta_updated_at IS NOT NULL OR p_expected_version IS NOT NULL THEN
      RAISE EXCEPTION 'BTCSP_VERSION_CONFLICT' USING ERRCODE='P0001';
    END IF;
    INSERT INTO public.projects(id,owner_id,name,mode,capital,archived)
      VALUES(p_id,v_uid,btrim(p_name),p_mode,p_capital,p_archived)
      RETURNING updated_at INTO v_meta;
    INSERT INTO public.project_snapshots(project_id,owner_id,payload,version)
      VALUES(p_id,v_uid,p_payload,1) RETURNING version INTO v_version;
  END IF;
  RETURN QUERY SELECT v_meta,v_version;
END
$function$
